    const std::string& getStreamId() const { return streamId_; }
    const std::string& getText() const { return text_; }

private:
    std::string commentId_, streamId_, userId_, text_;
};

class RateLimitExceededException : public std::runtime_error {
public:
    explicit RateLimitExceededException(const std::string& message) : std::runtime_error(message) {}
};

class ViewerConnection {
public:
    explicit ViewerConnection(std::string viewerId) : viewerId_(std::move(viewerId)) {}
    void send(const Comment& comment) { received_.push_back(comment); }
    void send(const std::vector<Comment>& recentHistory) {
        received_.insert(received_.end(), recentHistory.begin(), recentHistory.end());
    }
    const std::vector<Comment>& getReceived() const { return received_; }

private:
    std::string viewerId_;
    std::vector<Comment> received_;
};

class GatewayShard;

class PubSubBroker {
public:
    void subscribe(const std::string& topic, GatewayShard* shard) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscribersByTopic_[topic].push_back(shard);
    }
    void publish(const std::string& topic, const Comment& comment);

private:
    std::map<std::string, std::vector<GatewayShard*>> subscribersByTopic_;
    std::mutex mutex_;
};

class FanOutPublisher {
public:
    explicit FanOutPublisher(PubSubBroker* broker) : broker_(broker) {}
    void onCommentAccepted(const Comment& comment) {
        broker_->publish("stream." + comment.getStreamId(), comment);
    }

private:
    PubSubBroker* broker_;
};

class CommentQueueProducer {
public:
    explicit CommentQueueProducer(FanOutPublisher* fanOutPublisher) : fanOutPublisher_(fanOutPublisher) {}
    void publish(const std::string&, const Comment& comment) { fanOutPublisher_->onCommentAccepted(comment); }

private:
    FanOutPublisher* fanOutPublisher_;
};

class RateLimiter {
public:
    explicit RateLimiter(int maxTokens) : maxTokens_(maxTokens) {}
    void refill(const std::string& userId) { tokens_[userId] = maxTokens_; }
    bool tryConsume(const std::string& userId) {
        int current = tokens_.count(userId) ? tokens_[userId] : maxTokens_;
        if (current <= 0) return false;
        tokens_[userId] = current - 1;
        return true;
    }

private:
    std::map<std::string, int> tokens_;
    int maxTokens_;
};

std::string randomId() {
    static std::mt19937_64 rng(std::random_device{}());
    std::ostringstream oss;
    oss << std::hex << rng();
    return oss.str();
}

class CommentApiService {
public:
    CommentApiService(RateLimiter* rateLimiter, CommentQueueProducer* queueProducer)
        : rateLimiter_(rateLimiter), queueProducer_(queueProducer) {}

    Comment postComment(const std::string& streamId, const std::string& userId, const std::string& text) {
        if (!rateLimiter_->tryConsume(userId)) {
            throw RateLimitExceededException("User " + userId + " is posting too fast");
        }
        Comment comment(randomId(), streamId, userId, text);
        queueProducer_->publish(streamId, comment);
        return comment;
    }

private:
    RateLimiter* rateLimiter_;
    CommentQueueProducer* queueProducer_;
};

class GatewayShard {
public:
    void onViewerJoin(const std::string& streamId, ViewerConnection* connection, const std::vector<Comment>& recentHistory) {
        connectionsByStream_[streamId].push_back(connection);
        connection->send(recentHistory);
    }
    void onFannedOutComment(const std::string& streamId, const Comment& comment) {
        auto it = connectionsByStream_.find(streamId);
        if (it == connectionsByStream_.end()) return;
        for (auto* viewer : it->second) viewer->send(comment);
    }

private:
    std::map<std::string, std::vector<ViewerConnection*>> connectionsByStream_;
};

void PubSubBroker::publish(const std::string& topic, const Comment& comment) {
    auto it = subscribersByTopic_.find(topic);
    if (it == subscribersByTopic_.end()) return;
    for (auto* shard : it->second) shard->onFannedOutComment(comment.getStreamId(), comment);
}

int main() {
    PubSubBroker broker;
    FanOutPublisher fanOutPublisher(&broker);
    CommentQueueProducer queueProducer(&fanOutPublisher);
    RateLimiter rateLimiter(3);
    CommentApiService commentApi(&rateLimiter, &queueProducer);

    GatewayShard gatewayShard;
    broker.subscribe("stream.streamA", &gatewayShard);

    ViewerConnection alice("alice");
    ViewerConnection bob("bob");
    gatewayShard.onViewerJoin("streamA", &alice, {});
    gatewayShard.onViewerJoin("streamA", &bob, {});

    commentApi.postComment("streamA", "carol", "This game is amazing!");
    commentApi.postComment("streamA", "carol", "What a goal!");
    commentApi.postComment("streamA", "carol", "Unbelievable finish!");

    std::cout << "Alice received " << alice.getReceived().size() << " comments\n";
    std::cout << "Bob received " << bob.getReceived().size() << " comments\n";
    for (auto& c : alice.getReceived()) std::cout << "Alice saw: " << c.getText() << "\n";

    try {
        commentApi.postComment("streamA", "carol", "One more!");
    } catch (const RateLimitExceededException& e) {
        std::cout << "Caught expected: " << e.what() << "\n";
    }
    return 0;
}

