import java.util.*;
import java.util.concurrent.*;

// One comment posted to a live stream.
class Comment {
    private final String commentId;
    private final String streamId;
    private final String userId;
    private final String text;

    public Comment(String commentId, String streamId, String userId, String text) {
        this.commentId = commentId; // store id
        this.streamId = streamId;     // store which stream this belongs to
        this.userId = userId;           // store who posted it
        this.text = text;                 // store the comment text
    }

    public String getCommentId() { return commentId; } // id getter
    public String getStreamId() { return streamId; }       // stream getter
    public String getText() { return text; }                 // text getter
}

// Thrown when a user posts faster than their rate limit allows.
class RateLimitExceededException extends RuntimeException {
    public RateLimitExceededException(String message) { super(message); }
}

// A single viewer's open connection, capturing what has actually been
// pushed to it so this demo can verify fan-out reached every viewer.
class ViewerConnection {
    private final String viewerId;                              // who this connection belongs to
    private final List<Comment> received = new ArrayList<>();      // every comment delivered so far

    public ViewerConnection(String viewerId) {
        this.viewerId = viewerId; // store id
    }

    public void send(Comment comment) {
        received.add(comment); // record one comment as delivered
    }

    public void send(List<Comment> recentHistory) {
        received.addAll(recentHistory); // record a batch, used for join-time history
    }

    public List<Comment> getReceived() { return received; } // full delivery history getter
}

// In memory pub/sub broker: gateway shards subscribe to a stream's topic,
// and every publish is fanned out to every currently subscribed shard.
class PubSubBroker {
    private final Map<String, List<GatewayShard>> subscribersByTopic = new ConcurrentHashMap<>(); // topic -> subscribed shards

    public void subscribe(String topic, GatewayShard shard) {
        subscribersByTopic.computeIfAbsent(topic, k -> new ArrayList<>()).add(shard); // register this shard for the topic
    }

    public void publish(String topic, Comment comment) {
        List<GatewayShard> shards = subscribersByTopic.getOrDefault(topic, Collections.emptyList()); // every subscribed shard
        for (GatewayShard shard : shards) {
            shard.onFannedOutComment(comment.getStreamId(), comment); // deliver to each one
        }
    }
}

// Publishes accepted comments straight to the fan out layer.
class CommentQueueProducer {
    private final FanOutPublisher fanOutPublisher; // where accepted comments get published

    public CommentQueueProducer(FanOutPublisher fanOutPublisher) {
        this.fanOutPublisher = fanOutPublisher; // store the publisher
    }

    public void publish(String streamId, Comment comment) {
        fanOutPublisher.onCommentAccepted(comment); // hand off for fan out
    }
}

// Token bucket rate limiter, one bucket per user, refilled on a timer.
class RateLimiter {
    private final Map<String, Integer> tokens = new ConcurrentHashMap<>(); // userId -> tokens remaining
    private final int maxTokens;                                             // bucket capacity per user

    public RateLimiter(int maxTokens) {
        this.maxTokens = maxTokens; // store the per-user bucket capacity
    }

    // Called once per second per user by a background refill task.
    public void refill(String userId) {
        tokens.put(userId, maxTokens); // reset this user's bucket back to full
    }

    // Returns true if this comment is allowed, consuming one token if so.
    public boolean tryConsume(String userId) {
        int current = tokens.getOrDefault(userId, maxTokens); // this user's remaining tokens, full bucket if never seen before
        if (current <= 0) return false;                          // no tokens left, reject
        tokens.put(userId, current-1);                              // consume one token
        return true;                                                   // allowed
    }
}

// Comment API: validates, rate limits, then enqueues for downstream processing.
class CommentApiService {
    private final RateLimiter rateLimiter;             // gates how fast one user can post
    private final CommentQueueProducer queueProducer;    // hands accepted comments to the write path

    public CommentApiService(RateLimiter rateLimiter, CommentQueueProducer queueProducer) {
        this.rateLimiter = rateLimiter;       // store the rate limiter
        this.queueProducer = queueProducer;     // store the queue producer
    }

    public Comment postComment(String streamId, String userId, String text) {
        if (!rateLimiter.tryConsume(userId)) {                                     // this user is posting too fast
            throw new RateLimitExceededException("User " + userId + " is posting too fast");
        }
        Comment comment = new Comment(UUID.randomUUID().toString(), streamId, userId, text); // build the comment
        queueProducer.publish(streamId, comment); // ordered by streamId partition, hands off to the write path
        return comment; // hand back the accepted comment
    }
}

// Fan-out publisher: consumes accepted comments and pushes them to every
// gateway shard subscribed to that stream's channel.
class FanOutPublisher {
    private final PubSubBroker broker; // the pub/sub layer this publisher writes into

    public FanOutPublisher(PubSubBroker broker) {
        this.broker = broker; // store the broker
    }

    public void onCommentAccepted(Comment comment) {
        broker.publish("stream." + comment.getStreamId(), comment); // publish onto this stream's own channel
    }
}

// Gateway shard: holds live viewer connections and forwards fanned-out comments.
class GatewayShard {
    private final Map<String, List<ViewerConnection>> connectionsByStream = new ConcurrentHashMap<>(); // streamId -> connected viewers

    public void onViewerJoin(String streamId, ViewerConnection connection, List<Comment> recentHistory) {
        connectionsByStream.computeIfAbsent(streamId, k -> new CopyOnWriteArrayList<>()).add(connection); // register this viewer
        connection.send(recentHistory); // send recent history immediately on join
    }

    // Called by the pub/sub client whenever a new comment arrives for a subscribed stream.
    public void onFannedOutComment(String streamId, Comment comment) {
        List<ViewerConnection> viewers = connectionsByStream.getOrDefault(streamId, Collections.emptyList()); // every viewer on this stream
        for (ViewerConnection viewer : viewers) {
            viewer.send(comment); // push to every open socket for this stream
        }
    }
}

public class Main {
    public static void main(String[] args) {
        PubSubBroker broker = new PubSubBroker();                                  // the fan out layer
        FanOutPublisher fanOutPublisher = new FanOutPublisher(broker);                // publishes accepted comments to it
        CommentQueueProducer queueProducer = new CommentQueueProducer(fanOutPublisher); // stands in for the write queue
        RateLimiter rateLimiter = new RateLimiter(3);                                    // allow 3 comments before throttling
        CommentApiService commentApi = new CommentApiService(rateLimiter, queueProducer);  // the write path entry point

        GatewayShard gatewayShard = new GatewayShard();      // one shard holding this stream's viewers
        broker.subscribe("stream.streamA", gatewayShard);       // subscribe it to streamA's fan out channel

        ViewerConnection alice = new ViewerConnection("alice");   // first connected viewer
        ViewerConnection bob = new ViewerConnection("bob");          // second connected viewer
        gatewayShard.onViewerJoin("streamA", alice, Collections.emptyList()); // alice joins with no prior history
        gatewayShard.onViewerJoin("streamA", bob, Collections.emptyList());      // bob joins with no prior history

        commentApi.postComment("streamA", "carol", "This game is amazing!");  // 1st comment, within limit
        commentApi.postComment("streamA", "carol", "What a goal!");             // 2nd comment, within limit
        commentApi.postComment("streamA", "carol", "Unbelievable finish!");        // 3rd comment, exactly at limit

        System.out.println("Alice received " + alice.getReceived().size() + " comments"); // confirm fan out reached alice
        System.out.println("Bob received " + bob.getReceived().size() + " comments");        // confirm fan out reached bob too
        for (Comment c : alice.getReceived()) {
            System.out.println("Alice saw: " + c.getText()); // print each comment alice actually received
        }

        try {
            commentApi.postComment("streamA", "carol", "One more!"); // 4th comment, exceeds the limit of 3
        } catch (RateLimitExceededException e) {
            System.out.println("Caught expected: " + e.getMessage()); // confirm the rate limiter correctly rejected it
        }
    }
}
